import re
from ..section_generic import TextBasedSectionGeneric
from ..utils.logger import logger
from auto_config.generator.utils.utils import is_nr


class SectionRadio(TextBasedSectionGeneric):
    """
    Section "radio" is a part of cus.ini config file.
    Generated content base on enb.yaml and ue.yaml.
    Example generated for CLOUD_R4A_CUS:

    [radio_1]
    rmod_type = AHFB
    links     = 1.1:1:9.8
    link_type = CPRI
    """
    def __init__(self, subsection_separator='\n\n'):
        super().__init__(subsection_separator)
        self._section_header = '[radio_{}]'

    def _prepare_section_content(self, ue_config, enb_config, hw_config, *args, **kwargs):
        logger.debug("Generating Radio Section")
        overall_radio_id = 0
        for enb_key in enb_config.keys():
            for enb_radio_id in sorted(enb_config[enb_key]['radios'].keys(), key=int):
                radio_params = enb_config[enb_key]['radios'][enb_radio_id]
                overall_radio_id += 1
                links_speed, links_type = self.get_links_speed_and_type(radio_params)
                radio_link, cus_id = self.get_radio_link(hw_config, radio_params, enb_key)
                subsection_content = [
                    self._section_header.format(str(overall_radio_id)),
                    f'rmod_type = {radio_params["type"]}',
                    f'links     = {radio_link}:1:{links_speed}',
                    f'link_type = {links_type}'
                ]
                downlink_cpri_buffer_size = self.get_downlink_cpri_buffer_size(ue_config[f'cus{cus_id}'])
                if downlink_cpri_buffer_size is not None:
                    subsection_content.append(f'downlink_cpri_buffer_size = {downlink_cpri_buffer_size}')
                rat_type = self.get_rat_type(enb_config[enb_key])
                if rat_type is not None:
                    subsection_content.append(f'rat_type  = {rat_type}')
                ecpri_split_type = self.get_ecpri_split_type(radio_params)
                if ecpri_split_type is not None:
                    subsection_content.append(f'ecpri_split_type = {ecpri_split_type}')
                self._section_content.append(subsection_content)

    def get_rat_type(self, enb_ent):
        if is_nr(enb_ent):
            return '5G'
        return None

    @staticmethod
    def get_radio_link(hw_config, radio_params, bts_key):
        bbmod_or_smod_key = [key for key in radio_params if 'mod' in key]
        if not bbmod_or_smod_key:
            bbmod_or_smod_key = [key for key in radio_params if 'du' in key]
        bbmod_or_smod = f'{bbmod_or_smod_key[0]}_{radio_params[bbmod_or_smod_key[0]]}'
        cus_id_cus_link = hw_config['rf_links'][f'{bts_key}'][bbmod_or_smod][f'port{radio_params["port"]}']
        radio_link = ".".join(cus_id_cus_link.split('.')[1:])
        cus_id = cus_id_cus_link.split('.')[0]
        return radio_link, cus_id

    @staticmethod
    def get_downlink_cpri_buffer_size(cus_ent):
        if 'downlink_cpri_buffer_size' in cus_ent:
            return cus_ent['downlink_cpri_buffer_size']
        return None

    @staticmethod
    def get_links_speed_and_type(radio_params):
        link_speed_types = {
            'eCpri50': ['50', 'ECPRI'],
            'eCpri25': ['25', 'ECPRI'],
            'eCpri10': ['10', 'ECPRI'],
            'Cpri7': ['9.8', 'CPRI'],
            'Cpri6': ['6.1', 'CPRI'],
            'Cpri5': ['4.9', 'CPRI'],
            'Cpri3': ['2.4', 'CPRI'],
            '6Gbps': ['8x', 'OBSAI'],
            '3Gbps': ['4x', 'OBSAI']
        }
        links_speed = link_speed_types[radio_params['link_speed']][0]
        links_type = link_speed_types[radio_params['link_speed']][1]

        return links_speed, links_type

    @staticmethod
    def get_ecpri_split_type(radio_params):
        if 'protocol_version' in radio_params and radio_params['protocol_version'] == '72a':
            return 'DLUL72a'
        if 'protocol_version' in radio_params and radio_params['protocol_version'] == '72e':
            return 'DLUL72e'
        return None

    @staticmethod
    def _add_exit_lines():
        return '\n'

    @staticmethod
    def _get_cus_keys(ue_config):
        return sorted(key for key in ue_config if re.search(r'^cus\d+$', key))
